"""Stock availability for the web shop.

Rules:
- A paid reservation always holds its units. It never expires.
- An unpaid reservation holds its units while now_s - created_s < 300.
  At exactly 300 seconds it has expired, so the boundary is exclusive.
- A reservation whose created_s is in the future (clock skew) counts as active.
- The result is never below 0.
"""

import unittest

RESERVATION_TTL_S = 300


def _check_int(name, value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an int, got {type(value).__name__}")
    if value < 0:
        raise ValueError(f"{name} must be >= 0, got {value}")


def _check_number(name, value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be a number, got {type(value).__name__}")


def _is_holding(r, now_s, ttl_s):
    if r["paid"]:
        return True
    return now_s - r["created_s"] < ttl_s


def available(stock, reservations, now_s, ttl_s=RESERVATION_TTL_S):
    """Return how many units can still be sold (never less than 0)."""
    _check_int("stock", stock)
    _check_number("now_s", now_s)
    _check_number("ttl_s", ttl_s)

    held = 0
    for i, r in enumerate(reservations):
        if not isinstance(r, dict):
            raise TypeError(f"reservation {i} must be a dict")
        for key in ("qty", "created_s", "paid"):
            if key not in r:
                raise ValueError(f"reservation {i} is missing key {key!r}")
        _check_int(f"reservation {i} qty", r["qty"])
        _check_number(f"reservation {i} created_s", r["created_s"])
        if not isinstance(r["paid"], bool):
            raise TypeError(f"reservation {i} paid must be a bool")
        if _is_holding(r, now_s, ttl_s):
            held += r["qty"]

    return max(0, stock - held)


def _res(qty, created_s, paid=False):
    return {"qty": qty, "created_s": created_s, "paid": paid}


class AvailableTests(unittest.TestCase):
    def test_no_reservations(self):
        self.assertEqual(available(10, [], 1000), 10)

    def test_unpaid_active(self):
        self.assertEqual(available(10, [_res(3, 900)], 1000), 7)

    def test_unpaid_expired(self):
        self.assertEqual(available(10, [_res(3, 600)], 1000), 10)

    def test_unpaid_at_boundary_is_expired(self):
        self.assertEqual(available(10, [_res(3, 700)], 1000), 10)
        self.assertEqual(available(10, [_res(3, 701)], 1000), 7)

    def test_paid_never_expires(self):
        self.assertEqual(available(10, [_res(4, 0, paid=True)], 10**9), 6)

    def test_mixed(self):
        rs = [_res(2, 950), _res(3, 100), _res(1, 0, paid=True)]
        self.assertEqual(available(10, rs, 1000), 7)

    def test_oversubscribed_clamps_to_zero(self):
        self.assertEqual(available(3, [_res(5, 1000)], 1000), 0)

    def test_future_created_s_is_active(self):
        self.assertEqual(available(10, [_res(2, 1500)], 1000), 8)

    def test_qty_zero(self):
        self.assertEqual(available(5, [_res(0, 1000)], 1000), 5)

    def test_float_timestamps(self):
        self.assertEqual(available(5, [_res(1, 700.5)], 1000.0), 4)

    def test_rejects_non_int_stock(self):
        with self.assertRaises(TypeError):
            available(1.5, [], 0)
        with self.assertRaises(TypeError):
            available(True, [], 0)

    def test_rejects_non_int_qty(self):
        with self.assertRaises(TypeError):
            available(5, [_res(1.5, 0)], 0)
        with self.assertRaises(TypeError):
            available(5, [_res(True, 0)], 0)

    def test_rejects_negative(self):
        with self.assertRaises(ValueError):
            available(-1, [], 0)
        with self.assertRaises(ValueError):
            available(5, [_res(-1, 0)], 0)

    def test_rejects_missing_key(self):
        with self.assertRaises(ValueError):
            available(5, [{"qty": 1, "created_s": 0}], 0)

    def test_rejects_non_bool_paid(self):
        with self.assertRaises(TypeError):
            available(5, [{"qty": 1, "created_s": 0, "paid": "yes"}], 0)


if __name__ == "__main__":
    unittest.main()
